// CODEX hosting worker: runs every user project in its own resource-limited Docker container.
// Run this on a SEPARATE server (or at least outside the web app). It needs access to the Docker socket.
const express = require('express'), crypto = require('crypto'), Docker = require('dockerode'), AdmZip = require('adm-zip');
const fs = require('fs'), path = require('path'), { execFile } = require('child_process');
const docker = new Docker();
const DATA = path.resolve(process.env.WORKER_DATA || './data');
const SECRET = process.env.WORKER_SECRET || '';
if (SECRET.length < 16) { console.error('WORKER_SECRET must be 16+ chars'); process.exit(1); }
const IMG = { node: 'node:20-alpine', python: 'python:3.12-alpine' };
const bad = (s, m) => Object.assign(new Error(m), { status: s });
const wrap = (fn) => async (req, res) => {
  try { res.json((await fn(req)) ?? { ok: true }); }
  catch (e) { res.status(e.status || 500).json({ error: e.status ? e.message : 'Worker error: ' + e.message }); }
};
const app = express();
app.use((req, res, next) => {
  const a = Buffer.from(req.get('x-worker-secret') || ''), b = Buffer.from(SECRET);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return res.status(401).json({ error: 'unauthorized' });
