});
const sid = (id) => { if (!/^\d{1,9}$/.test(id)) throw bad(400, 'bad id'); return id; };
const base = (id) => { const d = path.join(DATA, 'servers', sid(id)); fs.mkdirSync(d, { recursive: true }); return d; };
// Resolve a user-supplied path and make sure it (and any symlink target) stays inside the server directory.
const inside = (b, rel) => {
  const rb = fs.realpathSync(b), full = path.resolve(b, String(rel || '.'));
  if (full !== b && !full.startsWith(b + path.sep)) throw bad(400, 'bad path');
  let p = full; while (!fs.existsSync(p)) p = path.dirname(p);
  const real = fs.realpathSync(p);
  if (real !== rb && !real.startsWith(rb + path.sep)) throw bad(400, 'bad path');
  return full;
};
const cname = (id) => 'codex-srv-' + sid(id);
async function getC(id) {
  const c = docker.getContainer(cname(id));
  try { return { c, i: await c.inspect() }; } catch (e) { if (e.statusCode === 404) return { c: null, i: null }; throw e; }
}
const kill = async (id) => { const { c } = await getC(id); if (c) await c.remove({ force: true }); };
async function ensureImage(img) {
  try { await docker.getImage(img).inspect(); }
  catch { await new Promise((ok, no) => docker.pull(img, (e, s) => e ? no(e) : docker.modem.followProgress(s, (er) => er ? no(er) : ok()))); }
}
async function start(id, cfg) {
  const rt = cfg.runtime; if (!IMG[rt]) throw bad(400, 'bad runtime');
  const cmd = String(cfg.start_cmd || '').slice(0, 200).replace(/[\r\n]/g, ' ').trim();
  if (!cmd) throw bad(400, 'start command required');
