  await kill(id); await ensureImage(IMG[rt]);
  const pre = rt === 'node' ? '[ -f package.json ] && npm install --no-audit --no-fund; ' : '[ -f requirements.txt ] && pip install --no-cache-dir -r requirements.txt --target /app/.pylibs; ';
  const env = Object.entries(cfg.env || {}).map(([k, v]) => k + '=' + v);
  env.push('HOME=/app/.home', 'npm_config_cache=/app/.npm', 'PYTHONPATH=/app/.pylibs', 'PYTHONUNBUFFERED=1');
  const mem = Math.max(64, Number(cfg.memory_mb) || 256) * 1048576;
  const c = await docker.createContainer({
    Image: IMG[rt], name: cname(id), Cmd: ['sh', '-c', pre + cmd], WorkingDir: '/app',
    User: process.getuid() + ':' + process.getgid(), Env: env, Labels: { codex: '1' },
    HostConfig: { Binds: [dir + ':/app'], Memory: mem, MemorySwap: mem, NanoCpus: Math.round((Number(cfg.cpu) || 0.5) * 1e9),
      PidsLimi
t: 128, CapDrop: ['ALL'], SecurityOpt: ['no-new-privileges'], RestartPolicy: { Name: 'on-failure', MaximumRetryCount: 3 } },
  });
  await c.start();
}
function demux(buf) { let o = '', i = 0; while (i + 8 <= buf.length) { const n = buf.readUInt32BE(i + 4); o += buf.slice(i + 8, i + 8 + n).toString('utf8'); i += 8 + n; } return o; }

app.post('/servers/:id/start', express.json(), wrap((r) => start(r.params.id, r.body || {})));
app.post('/servers/:id/stop', wrap(async (r) => { const { c } = await getC(r.params.id); if (c) { try { await c.stop({ t: 5 }); } catch (e) { if (e.statusCode !== 304) throw e; } } }));
app.get('/servers/:id/status', wrap(async (r) => { const { i } = await getC(r.params.id); return { status: i && i.State.Running ? 'online' : 'offline', exit_code: i ? i.State.ExitCode : null }; }));
app.get('/servers/:id/logs', wrap(async (r) => { const { c } = await getC(r.params.id); return { logs: c ? demux(await c.logs({ stdout: true, stderr: true, tail: 300 })) : '' }; }));
app.get('/servers/:id/stats', wrap(async (r) => {
  const { c, i } = await getC(r.params.id);
  if (!c || !i.State.Running) return { cpu: 0, mem_mb: 0, mem_limit_mb: 0 };
  const s = await c.stats({ stream: false });
  const cd = (s.cpu_stats.cpu_usage.total_usage || 0) - (s.precpu_stats.cpu_usage.total_usage || 0);
  const sd = (s.cpu_stats.system_cpu_usage || 0) - (s.precpu_stats.system_cpu_usage || 0);
  return { cpu: +(sd > 0 ? cd / sd * (s.cpu_stats.online_cpus || 1) * 100 : 0).toFixed(1),
    mem_mb: +((s.memory_stats.usage || 0) / 1048576).toFixed(1), mem_limit_mb: Math.round((s.memory_stats.limit || 0) / 1048576) };
}));
app.get('/servers/:id/files', wrap(async (r) => {
  const b = base(r.params.id), d = inside(b, r.query.path);
  if (!fs.statSync(d).isDirectory()) throw bad(400, 'not a directory');
  return { files: fs.readdirSync(d).map((n) => { const st = fs.lstatSync(path.join(d, n)); return { name: n, dir: st.isDirectory(), size: st.isFile() ? st.size : 0 }; })
    .sort((a, b) => b.dir - a.dir || a.name.localeCompare(b.name)) };
}));
app.get('/servers/:id/file', wrap(async (r) => {
  const f = inside(base(r.params.id), r.query.path), st = fs.statSync(f);
  if (!st.isFile() || st.size > 1048576) throw bad(400, 'not a file or larger than 1MB');
  return { content: fs.readFileSync(f, 'utf8') };
}));
app.put('/servers/:id/file', express.json({ limit: '2mb' }), wrap(async (r) => {
  const b = base(r.params.id), f = inside(b, r.body.path);
  if (f === b) throw bad(400, 'bad path');
  fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, String(r.body.content ?? ''));
}));
app.delete('/servers/:id/file', wrap(async (r) => {
  const b = base(r.params.id), f = inside(b, r.query.path);
  if (f === b) throw bad(400, 'bad path');
  fs.rmSync(f, { recursive: true, force: true });
}));
app.post('/servers/:id/upload', express.raw({ limit: '50mb', type: () => true }), wrap(async (r) => {
  const id = r.params.id, dir = base(id); await kill(id);
  let z; try { z = new AdmZip(r.body); } catch { throw bad(400, 'invalid zip'); }
  const es = z.getEntries().filter((e) => !e.isDirectory && !e.entryName.startsWith('__MACOSX'));
  if (!es.length) throw bad(400, 'empty zip');
  if (es.reduce((s, e) => s + e.header.size, 0) > 300 * 1048576) throw bad(400, 'zip too large when extracted');
  const tops = new Set(es.map((e) => e.entryName.split('/')[0]));
  const strip = tops.size === 1 && es.every((e) => e.entryName.includes('/')) ? [...tops][0] + '/' : '';
  for (const e of es) { const f = inside(dir, e.entryName.slice(strip.length)); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, e.getData()); }
  return { files: es.length };
}));
app.post('/servers/:id/import', express.
json(), wrap(async (r) => {
  const repo = String((r.body || {}).repo || '');
  if (!/^https:\/\/github\.com\/[\w.-]+\/[\w.-]+?(\.git)?$/.test(repo)) throw bad(400, 'Use a public https://github.com/user/repo URL');
  const id = r.params.id, dir = base(id); await kill(id);
  fs.rmSync(dir, { recursive: true, force: true }); fs.mkdirSync(dir, { recursive: true });
  await new Promise((ok, no) => execFile('git', ['clone', '--depth', '1', '--', repo, '.'], { cwd: dir, timeout: 120000, env: { PATH: process.env.PATH, GIT_TERMINAL_PROMPT: '0' } }, (e) => e ? no(bad(400, 'git clone failed')) : ok()));
