}));
app.delete('/servers/:id', wrap(async (r) => { await kill(r.params.id); fs.rmSync(base(r.params.id), { recursive: true, force: true }); }));
app.listen(process.env.PORT || 4000, process.env.HOST || '127.0.0.1', () => console.log('CODEX worker up'));
